//! Opaque command handler contract and cancellable session output, without business codecs.

use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};

use anyhow::Result;
use serde::Serialize;
use serde_json::Value;
use thiserror::Error;
use uuid::Uuid;

use super::protocol::{Reply, Status};

pub(crate) trait Command: Send + Sync + 'static {
    /// Stable string identifier; invocation GUIDs are generated by the client.
    const ID: &'static str;
    fn run(contents: Value, output: &Output) -> Result<()>;
}

pub(crate) struct Output {
    pub(super) guid: Uuid,
    pub(super) cancelled: Arc<AtomicBool>,
    pub(super) send: Arc<dyn Fn(Reply) -> Result<()> + Send + Sync>,
}

impl std::fmt::Debug for Output {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Output")
            .field("guid", &self.guid)
            .field("cancelled", &self.cancelled)
            .finish_non_exhaustive()
    }
}

impl Output {
    pub(crate) fn checkpoint(&self) -> Result<()> {
        if self.cancelled.load(Ordering::Acquire) {
            tracing::debug!(guid = %self.guid, "Remote command observed cancellation");
            return Err(Cancelled.into());
        }
        Ok(())
    }

    pub(crate) fn send(&self, contents: impl Serialize) -> Result<()> {
        self.checkpoint()?;
        tracing::trace!(guid = %self.guid, "Queueing remote command data");
        (self.send)(Reply::new(self.guid, Status::Data, contents)?)
    }
}

#[derive(Debug, Error)]
#[error("remote command was cancelled")]
pub(super) struct Cancelled;
